  static Sprite Load(string p){var s=AssetDatabase.LoadAssetAtPath<Sprite>(p+".png");if(!s)throw new InvalidOperationException(p);return s;}
  public static void Import(){foreach(var path in AssetDatabase.FindAssets("t:Texture2D",new[]{H.TrimEnd('/'),I.TrimEnd('/'),J.TrimEnd('/')}).Select(AssetDatabase.GUIDToAssetPath)){var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spritePixelsPerUnit=100;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.filterMode=FilterMode.Bilinear;i.wrapMode=TextureWrapMode.Clamp;i.maxTextureSize=4096;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();}}
  static void Layer(FarolParallaxLayer l,string path,float scale,float center,int order,Color tint,float overlap=.9f){var s=Load(path);l.gameObject.SetActive(true);l.width=s.bounds.size.x*scale*overlap;l.verticalCenter=center;l.mirrorRepeat=true;l.fadeDistance=5;l.fadeIn=true;l.fadeOut=true;foreach(var p in l.panels){p.sprite=s;p.transform.localScale=Vector3.one*scale;p.color=tint;p.sortingOrder=order;}}
  static void Platform(FarolSourceMarker m){var source=m.GetComponent<SpriteRenderer>();var collider=m.GetComponent<Collider2D>();if(!source||!collider)return;int pixels=Mathf.RoundToInt(collider.bounds.size.x*100);var s=Load(J+"pecas/plataforma_"+(m.name.Contains("log")?"log_":"ledge_")+pixels);float scale=collider.bounds.size.x/(s.rect.width/100-.04f);var old=m.transform.Find("Laje HQ — visual");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var child=new GameObject("Laje HQ — visual");child.transform.position=new Vector3(collider.bounds.center.x,collider.bounds.max.y+(.06f-s.bounds.size.y*.5f)*scale,0);child.transform.localScale=Vector3.one*scale;child.transform.SetParent(m.transform,true);var visual=child.AddComponent<SpriteRenderer>();visual.sprite=s;visual.sharedMaterial=source.sharedMaterial;visual.sortingOrder=source.sortingOrder+1;visual.sortingLayerID=source.sortingLayerID;var proxy=m.GetComponent<FarolPlatformArt>();if(!proxy)proxy=m.gameObject.AddComponent<FarolPlatformArt>();proxy.source=source;proxy.visual=visual;proxy.surface=m.GetComponent<FarolIslandSurface>();proxy.animator=m.GetComponent<Animator>();source.forceRenderingOff=true;}
  static void Suspension(FarolSourceMarker marker){var d=JObject.Parse(marker.originalJson);if((bool?)d["sway"]!=true)return;var b=marker.GetComponent<Collider2D>().bounds;// A marca resumida não serializa ropeTopY; consultar o mapa completo.
var map=JObject.Parse(UnityEngine.Object.FindFirstObjectByType<FarolIslandMechanics>().map.text);var definition=map["chunks"].SelectMany(c=>c["platforms"]??new JArray()).First(e=>Mathf.Abs((float)e["x"]-(float)d["x"])<.1f);float top=(1080-(float)definition["ropeTopY"])/100;var art=marker.GetComponent<FarolHangingPlatformArt>();if(!art)art=marker.gameObject.AddComponent<FarolHangingPlatformArt>();art.support=marker.GetComponent<Collider2D>();art.leftAnchor=new Vector3(b.min.x+.22f,top);art.rightAnchor=new Vector3(b.max.x-.22f,top);LineRenderer Line(string name){var old=marker.transform.Find(name);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var go=new GameObject(name);go.transform.SetParent(marker.transform,false);var l=go.AddComponent<LineRenderer>();l.useWorldSpace=true;l.positionCount=2;l.sharedMaterial=AssetDatabase.GetBuiltinExtraResource<Material>("Sprites-Default.mat");l.startWidth=l.endWidth=.06f;l.startColor=l.endColor=new Color(.55f,.4f,.21f);l.sortingOrder=10;return l;}art.left=Line("Corda de sustentação esquerda");art.right=Line("Corda de sustentação direita");art.left.SetPosition(0,art.leftAnchor);art.left.SetPosition(1,new Vector3(b.min.x+.22f,b.max.y));art.right.SetPosition(0,art.rightAnchor);art.right.SetPosition(1,new Vector3(b.max.x-.22f,b.max.y));}
  public static string Apply(){if(EditorApplication.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Salve e saia do Play.");foreach(var path in new[]{"Assets/Farol/Campanha_20261021_215901/Fase3_Ilha.unity","Assets/Farol/Visual/Bloco01/Fase3_Referencia.unity"}){
   var scene=EditorSceneManager.OpenScene(path);bool pilot=path.Contains("Referencia");var old=GameObject.Find("Clareira, riacho e cachoeira — HQ");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Clareira, riacho e cachoeira — HQ");
   foreach(var l in UnityEngine.Object.FindObjectsByType<FarolParallaxLayer>(FindObjectsInactive.Include,FindObjectsSortMode.None)){
    if(l.x0==0&&l.name=="Fundo camada 0")l.x1=768;
    if(Mathf.Abs(l.x0-460.8f)<.01f){l.fadeOut=true;l.fadeDistance=5;}
    bool h=Mathf.Abs(l.x0-537.6f)<.01f,i=Mathf.Abs(l.x0-614.4f)<.01f,j=Mathf.Abs(l.x0-691.2f)<.01f;if(!h&&!i&&!j)continue;
    if(h&&l.name=="Fundo camada 1"){Layer(l,FarolForestArtIntegration.Folder+"camadas/mata_distante_revisada",1.3f,8.04f,-43,new Color(.82f,.9f,.9f),1);l.x1=768;}
    else if(h&&l.name=="Fundo camada 3"){Layer(l,FarolForestArtIntegration.Folder+"camadas/cenarioC_3_floresta",.9f,6.12f,-31,new Color(.68f,.78f,.72f));l.x1=691.2f;}
    else if(j&&l.name=="Fundo camada 3")Layer(l,J+"camadas/cenarioJ_3_paredao_SEM_AGUA",1.4f,7.62f,-29,new Color(.75f,.85f,.84f),.84f);
