   }
   var markers=UnityEngine.Object.FindObjectsByType<FarolSourceMarker>(FindObjectsSortMode.None);foreach(string sector in new[]{"H","I","J"}){string folder=sector=="H"?H:sector=="I"?I:J;float offset=sector=="H"?537.6f:sector=="I"?614.4f:691.2f;var manifest=JArray.Parse(System.IO.File.ReadAllText(folder+"MANIFESTO.json"));int index=0;
    foreach(var m in markers.Where(m=>m.sector==sector&&m.category=="ground").OrderBy(m=>m.transform.position.x).ThenBy(m=>m.transform.position.y)){var c=m.GetComponent<Collider2D>();if(!c)continue;foreach(var sr in m.GetComponentsInChildren<SpriteRenderer>())sr.enabled=false;var b=c.bounds;bool rock=m.name.Contains("rock");FarolBeachArtIntegration.Ground(root.transform,b,rock,index++,pilot,rock?FarolCoastArtIntegration.Folder:FarolForestArtIntegration.Folder,rock?"rocha_umida_topo":"terra_grama_topo",rock?"rocha_umida_meio":"terra_meio",meshFolder:folder);
     var entry=manifest.FirstOrDefault(e=>e["posicao_mapa"]!=null&&Mathf.Abs((float)e["posicao_mapa"][0]/100+offset-b.min.x)<.03f&&Mathf.Abs((1080-(float)e["posicao_mapa"][1])/100-b.max.y)<.03f);if(entry!=null)FarolDEArtIntegration.Panel(root.transform,b,folder+((string)entry["arquivo"]).Replace(".png",""));
    }
    foreach(var m in markers.Where(m=>m.sector==sector&&m.category=="platforms")){if(sector=="J")Platform(m);else FarolForestArtIntegration.Platform(m,FarolDEArtIntegration.E);Suspension(m);}
    foreach(var m in markers.Where(m=>m.sector==sector&&m.category=="decor")){var sr=m.GetComponent<SpriteRenderer>();if(!sr)continue;string n=m.name;string file=n.Contains("tree")?FarolForestArtIntegration.Folder+"pecas/arvore_floresta_420x720":n.Contains("roots")?FarolForestArtIntegration.Folder+"pecas/raizes_280x130":n.Contains("fern")?FarolBeachArtIntegration.Folder+"pecas/samambaia-costeira":n.Contains("bush")?FarolBeachArtIntegration.Folder+"pecas/arbusto-costeiro":n.Contains("rock")||n.Contains("boulder")||n.Contains("pebbles")?FarolCoastArtIntegration.Folder+"pecas/pedra-costao-musgo":n.Contains("vine")?FarolDEArtIntegration.E+"pecas/cipo_pendente_120x380":null;if(file!=null)FarolForestArtIntegration.Decor(sr,file,n.Contains("tree")||n.Contains("vine")?-4:12);
     float secret=sector=="H"?573.05f:sector=="I"?637.4f:737.9f;if(Mathf.Abs(m.transform.position.x-secret)<3){var fade=m.GetComponent<FarolSecretSceneryFade>();if(!fade)fade=m.gameObject.AddComponent<FarolSecretSceneryFade>();fade.visual=sr;fade.secretId=sector=="H"?"moita-julia":sector=="I"?"margem-lucas":"atras-da-cachoeira";fade.centerX=secret;}
     // A árvore sobre a água de I1 pertence ao fundo, sem sugerir uma ilha sólida.
     if(sector=="I"&&n.Contains("tree")&&Mathf.Abs(m.transform.position.x-645.48f)<.1f){sr.sortingOrder=-34;sr.color=new Color(.64f,.76f,.72f);}
    }
   }
