   var seam=new Bounds();seam.SetMinMax(new Vector3(536.32f,-1.2f),new Vector3(538.88f,4.6f));int first=root.transform.childCount;FarolBeachArtIntegration.Ground(root.transform,seam,true,1000,pilot,FarolCoastArtIntegration.Folder,"rocha_umida_topo","rocha_umida_meio",meshFolder:H);for(int i=first;i<root.transform.childCount;i++){var t=root.transform.GetChild(i);var mesh=t.GetComponent<MeshFilter>().sharedMesh;var colors=mesh.colors;var vertices=mesh.vertices;for(int j=0;j<colors.Length;j++)colors[j].a*=Mathf.Clamp01(1-Mathf.Abs(vertices[j].x-537.6f)/1.28f);mesh.colors=colors;t.GetComponent<MeshRenderer>().sortingOrder+=4;EditorUtility.SetDirty(mesh);}
   var fg=UnityEngine.Object.FindFirstObjectByType<FarolBeachForeground>();if(fg)fg.sectorEnd=768;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }FarolVisualBlockOne.OpenCampaign();AssetDatabase.SaveAssets();return "H/I/J aplicados nas duas cenas.";}
